/// <summary>
/// AVA/WEN/2025/06/02  AVA_013382_FallbackInventLocation
/// </summary>
/// <param name = "_inventDim">InventDim</param>
public void setInventDimIdFromInventDim(InventDim _inventDim)
{
    InventDim   inventDim;

    inventDim = InventDim::findOrCreate(_inventDim);
    if (inventDim.InventSiteId && !inventDim.InventLocationId)
    {
        inventDim.InventLocationId = InventSite::find(inventDim.InventSiteId).AVAInventLocationIdDefault;
    }

    next setInventDimIdFromInventDim(inventDim);
}
